CREATE TYPE "OrganizationPermissionScope" AS ENUM ('ORGANIZATION', 'DEPARTMENT', 'TEAM', 'FLOW_PROJECT');
CREATE TABLE "organization_permission_groups" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "organizationId" UUID NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "isSystem" BOOLEAN NOT NULL DEFAULT false, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), CONSTRAINT "organization_permission_groups_pkey" PRIMARY KEY ("id"));
CREATE TABLE "organization_permission_group_permissions" ("permissionGroupId" UUID NOT NULL, "permissionId" UUID NOT NULL, CONSTRAINT "organization_permission_group_permissions_pkey" PRIMARY KEY ("permissionGroupId", "permissionId"));
CREATE TABLE "organization_permission_group_assignments" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "organizationId" UUID NOT NULL, "permissionGroupId" UUID NOT NULL, "userId" UUID NOT NULL, "scopeType" "OrganizationPermissionScope" NOT NULL DEFAULT 'ORGANIZATION', "departmentId" UUID, "teamId" UUID, "flowProjectId" UUID, "assignedByUserId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "revokedAt" TIMESTAMP(3), CONSTRAINT "organization_permission_group_assignments_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "organization_permission_groups_organizationId_name_key" ON "organization_permission_groups"("organizationId", "name");
CREATE INDEX "organization_permission_groups_organizationId_isActive_idx" ON "organization_permission_groups"("organizationId", "isActive");
CREATE INDEX "organization_permission_group_assignments_organizationId_userId_revokedAt_idx" ON "organization_permission_group_assignments"("organizationId", "userId", "revokedAt");
CREATE INDEX "organization_permission_group_assignments_permissionGroupId_userId_idx" ON "organization_permission_group_assignments"("permissionGroupId", "userId");
ALTER TABLE "organization_permission_groups" ADD CONSTRAINT "organization_permission_groups_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "organization_permission_group_permissions" ADD CONSTRAINT "organization_permission_group_permissions_permissionGroupId_fkey" FOREIGN KEY ("permissionGroupId") REFERENCES "organization_permission_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "organization_permission_group_permissions" ADD CONSTRAINT "organization_permission_group_permissions_permissionId_fkey" FOREIGN KEY ("permissionId") REFERENCES "permissions"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "organization_permission_group_assignments" ADD CONSTRAINT "organization_permission_group_assignments_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "organization_permission_group_assignments" ADD CONSTRAINT "organization_permission_group_assignments_permissionGroupId_fkey" FOREIGN KEY ("permissionGroupId") REFERENCES "organization_permission_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE;
